// login: store the payload server-side, keep only an opaque id in the cookie
val sid = UUID.randomUUID().toString
cache.set(s"session:$sid", SessionData(userId, cart), 30.minutes)
Redirect(routes.Home.index).withSession("sid" -> sid)

// each request: resolve the record before the action body
def cart(implicit request: Request[AnyContent]) =
  request.session.get("sid").flatMap(sid => cache.get[SessionData](s"session:$sid"))
    .map(data => Ok(Json.toJson(data.cart)))
    .getOrElse(Redirect(routes.Auth.login))
